insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1722','braille','Braille literacy','medium','classic','What is contracted Braille designed to do?','["Use approved contractions to represent text more compactly","Replace raised dots with color","Translate every language into speech automatically","Remove spaces between all words"]'::jsonb,'Use approved contractions to represent text more compactly','Contracted Braille uses signs that represent letter groups or words to make reading and writing more compact.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1723','braille','Braille literacy','medium','classic','What does uncontracted literary Braille generally represent?','["Text with letters written without word contractions","Only numbers and mathematical signs","A picture with no language","Speech sounds stored as audio"]'::jsonb,'Text with letters written without word contractions','Uncontracted Braille represents text without using the word and letter-group contractions found in contracted forms.',10,2,array['braille literacy'],'en',true,'BANA, The ABCs of UEB — https://www.brailleauthority.org/ueb/abcs/abcs-ueb.html ; Government of India/NIEPVD, Standard Bharati Braille Codes — https://cdnbbsr.s3waas.gov.in/s36ee69d3769e832ec77c9584e0b7ba112/uploads/2025/01/20250104954295710.pdf') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
