insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1743','management','Problem solving','medium','classic','What is root-cause analysis intended to identify?','["Underlying reasons a problem occurred","The person who should always be blamed","The price of replacing every tool","The first item on a meeting agenda"]'::jsonb,'Underlying reasons a problem occurred','Root-cause analysis seeks the underlying causes of a problem so corrective actions can address them.',10,2,array['problem solving'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
