insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1746','management','Project delivery','medium','classic','What is a project baseline?','["An approved reference plan used to compare actual progress","A list of every possible supplier","The final invoice from a contractor","A type of team-building exercise"]'::jsonb,'An approved reference plan used to compare actual progress','A baseline is an approved plan or set of measures against which project performance can be compared.',10,2,array['project delivery'],'en',true,'ISO 21502 project management guidance overview — https://www.iso.org/standard/74947.html ; UK Government Project Delivery Functional Standard — https://www.gov.uk/government/publications/project-delivery-functional-standard') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
