insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1895','food','Food science','medium','classic','What is a whole grain?','["A grain that retains its bran, germ, and endosperm","A grain with only its outer bran remaining","A grain from which every part has been removed","A grain that has been turned into syrup"]'::jsonb,'A grain that retains its bran, germ, and endosperm','Whole grains retain the bran, germ, and endosperm in the proportions found in the original kernel.',10,2,array['food science'],'en',true,'USDA Food Safety and Inspection Service — https://www.fsis.usda.gov/food-safety ; FoodSafety.gov — https://www.foodsafety.gov/ ; Encyclopaedia Britannica, Food — https://www.britannica.com/topic/food') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1896','food','Cooking methods','medium','classic','What is a water bath used for in some cooking and baking?','["Gentle, even heat around a dish","Freezing a dish without a freezer","Adding a crust by direct flame","Measuring the acidity of a liquid"]'::jsonb,'Gentle, even heat around a dish','A water bath surrounds a cooking vessel with hot water to moderate heat and reduce sudden temperature changes.',10,2,array['cooking methods'],'en',true,'USDA Food Safety and Inspection Service — https://www.fsis.usda.gov/food-safety ; FoodSafety.gov — https://www.foodsafety.gov/ ; Encyclopaedia Britannica, Food — https://www.britannica.com/topic/food') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1897','arts','Art forms','easy','classic','What is a portrait?','["An artwork representing a person or people","A painting of only a bowl of fruit","A map showing mountain heights","A sculpture made only for a building''s roof"]'::jsonb,'An artwork representing a person or people','A portrait is an artwork that represents a person or group, sometimes emphasizing character as well as likeness.',10,2,array['art forms'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
insert into public.bq_questions(id,category,subcategory,difficulty,mode,question,answers,correct_answer,explanation,xp_reward,coin_reward,tags,language,active,source_note) values ('bq-en-1898','arts','Art forms','easy','classic','What is a still life artwork usually focused on?','["Arranged inanimate objects","A moving sports competition","A wide view of a mountain range only","A portrait of a crowd in motion"]'::jsonb,'Arranged inanimate objects','Still life depicts arranged objects such as vessels, flowers, food, or household items.',10,2,array['art forms'],'en',true,'Tate Art Terms — https://www.tate.org.uk/art/art-terms ; The Metropolitan Museum of Art, Heilbrunn Timeline of Art History — https://www.metmuseum.org/toah/') on conflict(id) do update set category=excluded.category,subcategory=excluded.subcategory,difficulty=excluded.difficulty,mode=excluded.mode,question=excluded.question,answers=excluded.answers,correct_answer=excluded.correct_answer,explanation=excluded.explanation,xp_reward=excluded.xp_reward,coin_reward=excluded.coin_reward,tags=excluded.tags,language=excluded.language,active=excluded.active,source_note=excluded.source_note;
